class Solution
{
public:
    vector<vector<int>> multiply(vector<vector<int>>& mat1,
                                 vector<vector<int>>& mat2) {
        int m = mat1.size(), k = mat1[0].size(), n = mat2[0].size();
        vector<vector<int>> result(m, vector<int>(n, 0));
        for (int i = 0; i < m; ++i)
        {
            for (int t = 0; t < k; ++t)
            {
                if (mat1[i][t] == 0) continue;
                for (int j = 0; j < n; ++j)
                {
                    if (mat2[t][j] != 0)
                    {
                        result[i][j] += mat1[i][t] * mat2[t][j];
                    }
                }
            }
        }
        return result;
    }
};
